def choose_move(observation):
    w = observation["grid_width"]
    h = observation["grid_height"]
    sx, sy = observation["self_position"]
    ox, oy = observation["opponent_position"]
    resources = observation.get("resources") or []
    obstacles = observation.get("obstacles") or []
    obs_set = set(obstacles) if obstacles else set()

    moves = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]

    def inb(x, y):
        return 0 <= x < w and 0 <= y < h

    def cheb(x1, y1, x2, y2):
        dx = x1 - x2
        if dx < 0:
            dx = -dx
        dy = y1 - y2
        if dy < 0:
            dy = -dy
        return dx if dx > dy else dy

    best_val = None
    best_move = [0, 0]

    if resources:
        def nearest_dist(x, y):
            d = None
            for rx, ry in resources:
                t = cheb(x, y, rx, ry)
                if d is None or t < d:
                    d = t
            return d
        my_opp = nearest_dist(ox, oy)
        for dx, dy in moves:
            nx, ny = sx + dx, sy + dy
            if not inb(nx, ny) or (nx, ny) in obs_set:
                continue
            my_d = nearest_dist(nx, ny)
            if my_d is None:
                continue
            val = (my_opp - my_d) - 0.01 * cheb(nx, ny, ox, oy)
            if best_val is None or val > best_val:
                best_val = val
                best_move = [dx, dy]
    else:
        tx, ty = ox, oy
        for dx, dy in moves:
            nx, ny = sx + dx, sy + dy
            if not inb(nx, ny) or (nx, ny) in obs_set:
                continue
            val = -cheb(nx, ny, tx, ty)
            if best_val is None or val > best_val:
                best_val = val
                best_move = [dx, dy]

    return best_move

def choose_move(observation):
    w = int(observation.get("grid_width", 8))
    h = int(observation.get("grid_height", 8))
    sx, sy = observation.get("self_position", [0, 0])
    ox, oy = observation.get("opponent_position", [0, 0])
    moves = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]
    obs = observation.get("obstacles") or []
    obstacles = set()
    for p in obs:
        try:
            obstacles.add((int(p[0]), int(p[1])))
        except:
            pass

    def clamp(v, lo, hi):
        return lo if v < lo else (hi if v > hi else v)

    sx = clamp(int(sx), 0, w - 1)
    sy = clamp(int(sy), 0, h - 1)

    def valid(x, y):
        return 0 <= x < w and 0 <= y < h and (x, y) not in obstacles

    resources = observation.get("resources") or []
    target = None
    if resources:
        bestd = None
        for r in resources:
            try:
                tx, ty = int(r[0]), int(r[1])
            except:
                continue
            if not (0 <= tx < w and 0 <= ty < h) or (tx, ty) in obstacles:
                continue
            d = abs(tx - sx)
            dd = abs(ty - sy)
            if dd > d:
                d = dd
            if bestd is None or d < bestd or (d == bestd and (tx, ty) < target):
                bestd = d
                target = (tx, ty)

    if target is None:
        target = ((w - 1) // 2, (h - 1) // 2)

    def cheb(x1, y1, x2, y2):
        dx = x1 - x2
        if dx < 0:
            dx = -dx
        dy = y1 - y2
        if dy < 0:
            dy = -dy
        return dx if dx > dy else dy

    best_move = [0, 0]
    best_score = -10**18
    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if not valid(nx, ny):
            continue
        d_t = cheb(nx, ny, target[0], target[1])
        d_o = cheb(nx, ny, int(ox), int(oy))
        score = -d_t + 0.08 * d_o
        if score > best_score or (score == best_score and (dx, dy) < (best_move[0], best_move[1])):
            best_score = score
            best_move = [dx, dy]

    if not valid(sx + best_move[0], sy + best_move[1]):
        return [0, 0]
    return best_move

def choose_move(observation):
    w = int(observation.get("grid_width") or 8)
    h = int(observation.get("grid_height") or 8)
    s = observation.get("self_position") or (0, 0)
    o = observation.get("opponent_position") or (0, 0)
    sx, sy = int(s[0]), int(s[1])
    ox, oy = int(o[0]), int(o[1])
    sx = 0 if sx < 0 else (w - 1 if sx >= w else sx)
    sy = 0 if sy < 0 else (h - 1 if sy >= h else sy)
    ox = 0 if ox < 0 else (w - 1 if ox >= w else ox)
    oy = 0 if oy < 0 else (h - 1 if oy >= h else oy)

    obstacles = set()
    for p in observation.get("obstacles") or []:
        try:
            x, y = int(p[0]), int(p[1])
            if 0 <= x < w and 0 <= y < h:
                obstacles.add((x, y))
        except:
            pass

    resources = []
    for r in observation.get("resources") or []:
        try:
            x, y = int(r[0]), int(r[1])
            if 0 <= x < w and 0 <= y < h and (x, y) not in obstacles:
                resources.append((x, y))
        except:
            pass

    if not resources:
        return [0, 0]

    def md(ax, ay, bx, by):
        return abs(ax - bx) + abs(ay - by)

    def best_target():
        best = None
        for tx, ty in resources:
            ds = md(sx, sy, tx, ty)
            do = md(ox, oy, tx, ty)
            # Prefer resources where we are relatively closer (do - ds large),
            # then prefer closer resources for faster collection.
            key = (do - ds, -ds, tx, ty)
            if best is None or key > best[0]:
                best = (key, tx, ty)
        return best[1], best[2]

    tx, ty = best_target()

    best_move = [0, 0]
    best_val = -10**18

    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            nx, ny = sx + dx, sy + dy
            if not (0 <= nx < w and 0 <= ny < h):
                continue
            if (nx, ny) in obstacles:
                continue
            ns = md(nx, ny, tx, ty)
            no = md(ox, oy, tx, ty)

            # Compare progress vs opponent: maximize relative advantage after move.
            # Small bias toward staying nearer to current best target.
            rel = (no - ns)
            val = rel * 100 - ns

            # If a move is adjacent to any resource, give a slight push (collection soon).
            adj = 0
            for rx, ry in resources:
                d = max(abs(rx - nx), abs(ry - ny))
                if d == 0:
                    adj = 5
                    break
                if d == 1:
                    adj = max(adj, 1)
            val += adj

            if val > best_val:
                best_val = val
                best_move = [dx, dy]

    return best_move

def choose_move(observation):
    w = observation["grid_width"]
    h = observation["grid_height"]
    sx, sy = observation["self_position"]
    ox, oy = observation["opponent_position"]
    resources = observation.get("resources") or []
    obstacles = observation.get("obstacles") or []
    obs_set = set((x, y) for x, y in obstacles)

    def inb(x, y):
        return 0 <= x < w and 0 <= y < h

    def dist(x1, y1, x2, y2):
        return max(abs(x1 - x2), abs(y1 - y2))

    def safe_moves_to(tx, ty):
        candidates = []
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                nx, ny = sx + dx, sy + dy
                if inb(nx, ny) and (nx, ny) not in obs_set:
                    candidates.append((dist(nx, ny, tx, ty), dx, dy))
        if not candidates:
            return [0, 0]
        candidates.sort(key=lambda t: (t[0], t[1], t[2]))
        return [candidates[0][1], candidates[0][2]]

    # If stuck on an obstacle (shouldn't), step to a safe cell deterministically
    if (sx, sy) in obs_set:
        for dx in (1, 0, -1):
            for dy in (0, 1, -1):
                nx, ny = sx + dx, sy + dy
                if inb(nx, ny) and (nx, ny) not in obs_set:
                    return [dx, dy]
        return [0, 0]

    # Targeting: pick resource maximizing advantage (opp_time - self_time), discourage near obstacles
    best = None
    best_score = -10**18
    for rx, ry in resources:
        if (rx, ry) in obs_set:
            continue
        sd = dist(sx, sy, rx, ry)
        od = dist(ox, oy, rx, ry)
        if sd == 0:
            advantage = 999999
        else:
            advantage = od - sd
        # obstacle proximity penalty
        near = 0
        for ax in (rx - 1, rx, rx + 1):
            for ay in (ry - 1, ry, ry + 1):
                if (ax, ay) in obs_set:
                    near += 1
        score = advantage * 100 - near * 10 - sd
        if score > best_score:
            best_score = score
            best = (rx, ry, sd, od)

    # If no advantageous target, move to an "interference" point: reduce likelihood opponent wins next
    if best is None or best[2] >= best[3]:
        mx = (sx + ox) // 2
        my = (sy + oy) // 2
        # bias toward center for tie-breaking
        cx, cy = (w - 1) // 2, (h - 1) // 2
        tx = cx if abs(cx - mx) <= abs(cy - my) else mx
        ty = cy if abs(cx - mx) > abs(cy - my) else my
        tx = max(0, min(w - 1, tx))
        ty = max(0, min(h - 1, ty))
        return safe_moves_to(tx, ty)

    rx, ry, _, _ = best
    return safe_moves_to(rx, ry)

