        if best is None or key < best[0]:
            best = (key, (tx, ty))

    tx, ty = best[1]
    dx = 0 if tx == sx else (1 if tx > sx else -1)
    dy = 0 if ty == sy else (1 if ty > sy else -1)

    # Small bias to avoid stepping into obstacles if target cell is blocked (rare, but keep safe).
    nx, ny = sx + dx, sy + dy
